-- Migration 004: Biological Science Stream Canonical Syllabus & Trilingual Units

-- 1. Alter public.subjects to support tamil
ALTER TABLE public.subjects ADD COLUMN IF NOT EXISTS tamil TEXT;

-- 2. Alter public.syllabus_units to support tamil_title
ALTER TABLE public.syllabus_units ADD COLUMN IF NOT EXISTS tamil_title TEXT;

-- 3. Alter public.syllabus_subunits to support sinhala_title and tamil_title
ALTER TABLE public.syllabus_subunits 
  ADD COLUMN IF NOT EXISTS sinhala_title TEXT,
  ADD COLUMN IF NOT EXISTS tamil_title TEXT;

-- 4. Alter public.canonical_syllabus to store multilingual metadata
