('AGRI', 8, 'Unit 8: Post-Harvest Technology', 'Post-Harvest Technology', 'පසු අස්වනු තාක්ෂණය', 'அறுவடைக்குப் பிந்தைய தொழில்நுட்பம்', '8.2', 'Food processing, value addition and preservation', 'Food processing, value addition and preservation', 'ආහාර සැකසුම්කරණය, අගය එකතු කිරීම සහ කල්තබා ගැනීම', 'உணவு பதப்படுத்தலும் பெறுமதி சேர்த்தலும் பேணலும்'),
('AGRI', 9, 'Unit 9: Livestock Production and Management', 'Livestock Production and Management', 'පශු සම්පත් නිෂ්පාදනය සහ කළමනාකරණය', 'கால்நடை உற்பத்தியும் முகாமைத்துவமும்', '9.1', 'Dairy, cattle and poultry farming systems', 'Dairy, cattle and poultry farming systems', 'කිරි ගව සහ කුකුළු පාලන ක්‍රම', 'பால் பண்ணை மற்றும் கோழி வளர்ப்பு அமைப்புகள்'),
('AGRI', 9, 'Unit 9: Livestock Production and Management', 'Livestock Production and Management', 'පශු සම්පත් නිෂ්පාදනය සහ කළමනාකරණය', 'கால்நடை உற்பத்தியும் முகாமைத்துவமும்', '9.2', 'Animal feeds, breeding and animal health', 'Animal feeds, breeding and animal health', 'සත්ත්ව ආහාර, ප්‍රජනනය සහ සත්ත්ව සෞඛ්‍යය', 'விலங்குத் தீவனங்களும் இனப்பெருக்கமும் சுகாதாரமும்'),
('AGRI', 10, 'Unit 10: Farm Machinery and Structures', 'Farm Machinery and Structures', 'ගොවිපළ යන්ත්‍රෝපකරණ සහ ව්‍යූහ', 'பண்ணை இயந்திரங்களும் அமைப்புகளும்', '10.1', 'Tractors, implements and harvesting machinery', 'Tractors, implements and harvesting machinery', 'ට්‍රැක්ටර්, උපකරණ සහ අස්වනු නෙළන යන්ත්‍ර', 'உழவு இயந்திரங்கள், கருவிகள், அறுவடை இயந்திரங்கள்'),
('AGRI', 10, 'Unit 10: Farm Machinery and Structures', 'Farm Machinery and Structures', 'ගොවිපළ යන්ත්‍රෝපකරණ සහ ව්‍යූහ', 'பண்ணை இயந்திரங்களும் அமைப்புகளும்', '10.2', 'Greenhouses and farm building layouts', 'Greenhouses and farm building layouts', 'හරිතාගාර සහ ගොවිපළ ගොඩනැගිලි සැකසුම්', 'பச்சை இல்லங்களும் பண்ணைக் கட்டட அமைப்புகளும்'),
('AGRI', 11, 'Unit 11: Agricultural Economics and Agribusiness', 'Agricultural Economics and Agribusiness', 'කෘෂිකාර්මික ආර්ථික විද්‍යාව සහ කෘෂි ව්‍යාපාර', 'விவசாயப் பொருளியலும் விவசாய வணிகமும்', '11.1', 'Agricultural marketing and supply chain systems', 'Agricultural marketing and supply chain systems', 'කෘෂිකාර්මික අලෙවිකරණය සහ සැපයුම් දාම', 'விவசாய சந்தைப்படுத்தலும் விநியோகச் சங்கிலி அமைப்புகளும்'),
('AGRI', 11, 'Unit 11: Agricultural Economics and Agribusiness', 'Agricultural Economics and Agribusiness', 'කෘෂිකාර්මික ආර්ථික විද්‍යාව සහ කෘෂි ව්‍යාපාර', 'விவசாயப் பொருளியலும் விவசாய வணிகமும்', '11.2', 'Farm accounting and project evaluation', 'Farm accounting and project evaluation', 'ගොවිපළ ගිණුම්කරණය සහ ව්‍යාපෘති ඇගයීම', 'பண்ணைக் கணக்கியலும் திட்ட மதிப்பீடும்'),
('AGRI', 12, 'Unit 12: Sustainable Agriculture and Forestry', 'Sustainable Agriculture and Forestry', 'තිරසර කෘෂිකර්මාන්තය සහ වන විද්‍යාව', 'நிலைபேறான விவசாயமும் வனவியலும்', '12.1', 'Organic farming and soil conservation practices', 'Organic farming and soil conservation practices', 'කාබනික ගොවිතැන සහ පාංශු සංරක්ෂණ පිළිවෙත්', 'சேதன விவசாயமும் மண் பாதுகாப்பு நடைமுறைகளும்'),
('AGRI', 12, 'Unit 12: Sustainable Agriculture and Forestry', 'Sustainable Agriculture and Forestry', 'තිරසර කෘෂිකර්මාන්තය සහ වන විද්‍යාව', 'நிலைபேறான விவசாயமும் வனவியலும்', '12.2', 'Agroforestry and natural resource management', 'Agroforestry and natural resource management', 'කෘෂි වන විද්‍යාව සහ ස්වභාවික සම්පත් කළමනාකරණය', 'விவசாய வனவியலும் இயற்கை வள முகாமைத்துவமும்')
ON CONFLICT (subject, sub_lesson_code) DO UPDATE SET
  unit_number = EXCLUDED.unit_number,
  unit_name = EXCLUDED.unit_name,
  unit_name_en = EXCLUDED.unit_name_en,
  unit_name_si = EXCLUDED.unit_name_si,
  unit_name_ta = EXCLUDED.unit_name_ta,
  sub_lesson_title = EXCLUDED.sub_lesson_title,
  sub_lesson_title_en = EXCLUDED.sub_lesson_title_en,
  sub_lesson_title_si = EXCLUDED.sub_lesson_title_si,
  sub_lesson_title_ta = EXCLUDED.sub_lesson_title_ta;

-- 6. Helper function to seed user syllabus from canonical data with trilingual support
CREATE OR REPLACE FUNCTION public.seed_user_syllabus_from_canonical(p_user_id UUID)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
AS 236152
DECLARE
  v_sub RECORD;
  v_unit RECORD;
  v_unit_id UUID;
  v_canon_sub TEXT;
BEGIN
  FOR v_sub IN SELECT id, slug, code, name FROM public.subjects WHERE user_id = p_user_id LOOP
    -- Determine canonical subject key
    v_canon_sub := NULL;
    IF UPPER(v_sub.code) IN ('BIO', '09', 'AL-001', 'SUBJ-001') OR v_sub.slug ILIKE '%bio%' OR v_sub.name ILIKE '%biology%' THEN
      v_canon_sub := 'BIO';
    ELSIF UPPER(v_sub.code) IN ('CHEM', '10', 'AL-002', 'SUBJ-002') OR v_sub.slug ILIKE '%chem%' OR v_sub.name ILIKE '%chemistry%' THEN
      v_canon_sub := 'CHEM';
    ELSIF UPPER(v_sub.code) IN ('PHYS', '01', 'AL-003', 'SUBJ-003') OR v_sub.slug ILIKE '%phys%' OR v_sub.name ILIKE '%physics%' THEN
      v_canon_sub := 'PHYS';
    ELSIF UPPER(v_sub.code) IN ('AGRI', '08', 'AL-006', 'SUBJ-006') OR v_sub.slug ILIKE '%agri%' OR v_sub.name ILIKE '%agri%' THEN
      v_canon_sub := 'AGRI';
    ELSIF UPPER(v_sub.code) IN ('ET', 'AL-007', 'SUBJ-007') OR v_sub.slug ILIKE '%et%' OR v_sub.name ILIKE '%engineering tech%' THEN
      v_canon_sub := 'ET';
    ELSIF UPPER(v_sub.code) IN ('SFT', 'AL-008', 'SUBJ-008') OR v_sub.slug ILIKE '%sft%' OR v_sub.name ILIKE '%science for tech%' THEN
      v_canon_sub := 'SFT';
    ELSIF UPPER(v_sub.code) IN ('ICT', '005', 'AL-005', 'SUBJ-005') OR v_sub.slug ILIKE '%ict%' OR v_sub.name ILIKE '%information%' THEN
      v_canon_sub := 'ICT';
    ELSE
      -- Fallback to exact match with code or slug
      SELECT subject INTO v_canon_sub FROM public.canonical_syllabus 
      WHERE UPPER(subject) = UPPER(v_sub.code) OR UPPER(subject) = UPPER(v_sub.slug) 
      LIMIT 1;
    END IF;

    IF v_canon_sub IS NOT NULL THEN
      -- Delete existing units and subunits for this subject
      DELETE FROM public.syllabus_units WHERE subject_id = v_sub.id;

      -- Insert units from canonical_syllabus
      FOR v_unit IN 
        SELECT DISTINCT unit_number, 
               COALESCE(unit_name_en, regexp_replace(unit_name, '^ඒකකය\s*\d+\s*:\s*', '')) AS u_title,
               COALESCE(unit_name_si, unit_name) AS u_si,
               unit_name_ta AS u_ta
        FROM public.canonical_syllabus 
        WHERE subject = v_canon_sub
        ORDER BY unit_number
      LOOP
        INSERT INTO public.syllabus_units (subject_id, unit_number, title, sinhala_title, tamil_title)
        VALUES (v_sub.id, v_unit.unit_number, v_unit.u_title, v_unit.u_si, v_unit.u_ta)
        RETURNING id INTO v_unit_id;

        -- Insert subunits with trilingual titles
        INSERT INTO public.syllabus_subunits (unit_id, sub_number, title, sinhala_title, tamil_title, target_hours)
        SELECT 
          v_unit_id, 
          sub_lesson_code, 
          COALESCE(sub_lesson_title_en, sub_lesson_title),
          COALESCE(sub_lesson_title_si, sub_lesson_title),
          sub_lesson_title_ta,
          4
        FROM public.canonical_syllabus
        WHERE subject = v_canon_sub AND unit_number = v_unit.unit_number
        ORDER BY sub_lesson_code;
      END LOOP;
    END IF;
  END LOOP;
END;
$$;

-- 7. Seed any existing users automatically
DO $$
DECLARE
  u RECORD;
BEGIN
  FOR u IN SELECT id FROM public.profiles LOOP
    PERFORM public.seed_user_syllabus_from_canonical(u.id);
  END LOOP;
END;
$$;
